POST /webhook/newsletter-pipeline
Header: X-Webhook-Token: <N8N_WEBHOOK_TOKEN>

Body options:
  blocks mode:  { "raw_news_file": "data/sample/nyc_updates.json", "generate_images": true }
  flat mode:    { "content_file": "data/sample/newsletter_content.json", "generate_images": true }

parameters.functionCode:
const body = $input.first().json;

// Sanitize any string fields used in shell commands
const sanitize = (s) => (s || '').replace(/[`$();|&<>\\]/g, ' ').trim();

const params = {
  // blocks mode: raw news → AI snippet generation → blocks JSON
  raw_news_file: body.raw_news_file || null,

  // flat mode: pre-authored content JSON (legacy)
  content_file: body.content_file || 'data/sample/newsletter_content.json',

  // image generation
  generate_images: body.generate_images !== false,
  image_prompt: sanitize(body.image_prompt || 'NYC cityscape editorial photography professional'),
  image_ratio: body.image_ratio || '16:9',

  // pipeline mode: 'blocks' or 'flat'
  mode: body.raw_news_file ? 'blocks' : 'flat',

  timestamp: new Date().toISOString()
};

console.log('Pipeline parameters:', JSON.stringify(params, null, 2));
return [{ json: params }];

const cmdResult = $input.first().json;
const params = $node['Set Pipeline Parameters'].json;

if (cmdResult.exitCode !== 0) {
  throw new Error('Snippet generation failed:\n' + (cmdResult.stderr || cmdResult.stdout || 'unknown error'));
}

// Extract the output blocks file path from stdout
const stdout = cmdResult.stdout || '';
const pathMatch = stdout.match(/Blocks saved:\s*(.+\.json)/);
const blocksFile = pathMatch ? pathMatch[1].trim() : null;

if (!blocksFile) {
  throw new Error('Could not find blocks output path in generate_snippets.py output.\nstdout: ' + stdout);
}

console.log('Snippet blocks file:', blocksFile);
return [{ json: { ...params, content_file: blocksFile, blocks_file: blocksFile } }];

const result = $input.first().json;

// Accept result from either validate path
const params = $node['Set Pipeline Parameters'].json;

if (result.exitCode !== 0) {
  throw new Error('Content validation failed:\n' + (result.stderr || result.stdout || 'unknown error'));
}
console.log('Validation passed:', result.stdout);

// Merge in the content_file from whichever step updated it
// (blocks mode updated content_file to the blocks output path)
const blocksResult = $node['Parse Snippet Generation Result'] ? $node['Parse Snippet Generation Result'].json : null;
const mergedParams = blocksResult ? blocksResult : params;

return [{ json: mergedParams }];

const cmdResult = $input.first().json;
const params = $node['Check Validation Result'].json;

let imagePath = null;

if (cmdResult.exitCode === 0) {
  try {
    const stdout = cmdResult.stdout || '';
    const jsonMatch = stdout.match(/\{[\s\S]*\}/);
    const parsed = JSON.parse(jsonMatch ? jsonMatch[0] : stdout);
    imagePath = parsed.images && parsed.images[0] ? parsed.images[0] : null;
  } catch (e) {
    console.warn('Could not parse image output — continuing without image:', e.message);
  }
} else {
  console.warn('Image generation failed — continuing without image.');
  console.warn(cmdResult.stderr);
}

return [{ json: { ...params, image_path: imagePath } }];

const cmdResult = $input.first().json;
const params = $node['Parse Image Result'].json;

if (cmdResult.exitCode !== 0) {
  throw new Error('HTML rendering failed:\n' + (cmdResult.stderr || cmdResult.stdout || 'unknown error'));
}

const stdout = cmdResult.stdout || '';
const pathMatch = stdout.match(/Preview saved:\s*(.+\.html)/);
const htmlPath = pathMatch ? pathMatch[1].trim() : 'data/output/ (check for latest .html file)';

const summary = {
  status: 'success',
  timestamp: params.timestamp,
  mode: params.mode,
  content_file: params.content_file,
  blocks_file: params.blocks_file || null,
  html_preview: htmlPath,
  image_path: params.image_path,
  message: 'Newsletter rendered successfully. Open the HTML file to review.'
};

console.log('Pipeline complete:', JSON.stringify(summary, null, 2));
return [{ json: summary }];
